//! `detect_content_type`: what Active Storage records for an upload.
//!
//! Rails calls `Marcel::MimeType.for(io, name: filename.to_s, declared_type:
//! content_type)` (see `ActiveStorage::Blob#extract_content_type`). This is a
//! port of that algorithm running on Marcel's own tables, generated by
//! `tests/fixtures/gen_marcel_tables.rb`; `tests/fixtures/content_type_corpus.json`
//! (answers recorded from Rails' Marcel) pins the results.

use super::marcel_tables;
use std::collections::HashMap;
use std::sync::{LazyLock, Mutex};

pub const BINARY: &str = "application/octet-stream";

/// One magic rule: bytes (or a regex) at an offset, optionally within a range,
/// with child rules that must also match.
pub struct Match {
    pub start: usize,
    pub end: Option<usize>,
    pub value: Value,
    pub children: &'static [Match],
}

pub enum Value {
    /// A rule Marcel never matches (nil value).
    Never,
    Bytes(&'static [u8]),
    Regex(&'static str),
}

/// Bytes worth reading from the start of a file before calling
/// [`detect_content_type`]: no magic rule looks further.
pub const SNIFF_BYTES: usize = marcel_tables::MAX_READ;

/// `Marcel::MimeType.for(io, name: filename, declared_type: declared)`.
///
/// `head` is the start of the file (at least [`SNIFF_BYTES`] when available;
/// longer input is ignored beyond that). The file name goes through the same
/// sanitisation as `ActiveStorage::Filename#to_s`.
pub fn detect_content_type(head: &[u8], filename: Option<&str>, declared: Option<&str>) -> String {
    let head = &head[..head.len().min(SNIFF_BYTES)];
    let candidates = [
        by_magic(head).map(str::to_owned),
        declared.and_then(for_declared_type),
        filename.and_then(|name| for_name(&sanitize_filename(name))),
        Some(BINARY.to_owned()),
    ];
    let mut seen: Vec<String> = Vec::new();
    for candidate in candidates.into_iter().flatten() {
        if !seen.contains(&candidate) {
            seen.push(candidate);
        }
    }
    let mut iter = seen.into_iter();
    let first = iter.next().unwrap_or_else(|| BINARY.to_owned());
    iter.fold(first, |kind, candidate| {
        if is_child(&candidate, &kind, 0) {
            candidate
        } else {
            kind
        }
    })
}

/// `ActiveStorage::Filename#sanitized`.
fn sanitize_filename(name: &str) -> String {
    const BLANK: &[char] = &['\0', '\t', '\n', '\u{b}', '\u{c}', '\r', ' '];
    name.trim_matches(BLANK)
        .chars()
        .map(|c| {
            if "\u{202E}%$|:;/<>?*\"\\".contains(c) {
                '-'
            } else {
                c
            }
        })
        .collect()
}

/// `Marcel::MimeType.parse_media_type` minus the octet-stream rule.
fn for_declared_type(declared: &str) -> Option<String> {
    let lower = declared.to_lowercase();
    let end = lower
        .find([';', ',', ' ', '\t', '\n', '\r', '\u{b}', '\u{c}'])
        .unwrap_or(lower.len());
    let kind = &lower[..end];
    (kind.contains('/') && kind != BINARY).then(|| kind.to_owned())
}

/// Ruby's `File.extname`: last dot of the basename, ignoring leading dots.
fn extname(path: &str) -> &str {
    let base = path.rsplit('/').next().unwrap_or(path);
    let rest = base.trim_start_matches('.');
    match rest.rfind('.') {
        Some(i) => &rest[i..],
        None => "",
    }
}

fn for_name(name: &str) -> Option<String> {
    let ext = extname(name).to_lowercase();
    let key = ext.strip_prefix('.').unwrap_or(&ext);
    marcel_tables::EXTENSIONS
        .binary_search_by_key(&key, |(k, _)| k)
        .ok()
        .map(|i| marcel_tables::EXTENSIONS[i].1.to_owned())
}

fn is_child(child: &str, parent: &str, depth: usize) -> bool {
    if child == parent {
        return true;
    }
    if depth > 32 {
        return false;
    }
    match marcel_tables::PARENTS.binary_search_by_key(&child, |(k, _)| k) {
        Ok(i) => marcel_tables::PARENTS[i]
            .1
            .iter()
            .any(|p| is_child(p, parent, depth + 1)),
        Err(_) => false,
    }
}

fn by_magic(head: &[u8]) -> Option<&'static str> {
    marcel_tables::MAGIC
        .iter()
        .find(|(_, rules)| any_match(head, rules))
        .map(|(kind, _)| *kind)
}

fn any_match(head: &[u8], rules: &[Match]) -> bool {
    rules.iter().any(|rule| {
        rule_matches(head, rule) && (rule.children.is_empty() || any_match(head, rule.children))
    })
}

/// `io.read(start); io.read(len)`: nothing once the start is past the end.
fn window(head: &[u8], start: usize, len: usize) -> Option<&[u8]> {
    if len == 0 {
        return Some(&[]);
    }
    if start >= head.len() {
        return None;
    }
    Some(&head[start..head.len().min(start.saturating_add(len))])
}

fn rule_matches(head: &[u8], rule: &Match) -> bool {
    match &rule.value {
        Value::Never => false,
        Value::Bytes(value) => match rule.end {
            Some(end) => window(head, rule.start, end - rule.start + value.len())
                .is_some_and(|w| contains(w, value)),
            None => window(head, rule.start, value.len()).is_some_and(|w| w == *value),
        },
        Value::Regex(source) => window(head, rule.start, 256)
            .is_some_and(|w| regex_for(source).is_some_and(|re| re.is_match(w))),
    }
}

fn contains(haystack: &[u8], needle: &[u8]) -> bool {
    needle.is_empty() || haystack.windows(needle.len()).any(|w| w == needle)
}

/// Marcel's three regexes are byte patterns; compiled once.
fn regex_for(source: &'static str) -> Option<regex::bytes::Regex> {
    static CACHE: LazyLock<Mutex<HashMap<&'static str, Option<regex::bytes::Regex>>>> =
        LazyLock::new(Default::default);
    let mut cache = CACHE.lock().unwrap_or_else(|e| e.into_inner());
    cache
        .entry(source)
        .or_insert_with(|| {
            regex::bytes::Regex::new(&format!("(?-u){}", source.replace("\\u0000", "\\x00"))).ok()
        })
        .clone()
}

#[cfg(test)]
mod tests {
    use super::*;
    use base64::Engine;

    fn detect(data: &[u8], name: &str, declared: Option<&str>) -> String {
        detect_content_type(data, Some(name), declared)
    }

    // Answers below were read off the Rails stack's Marcel 1.2.1 (see the corpus).
    #[test]
    fn pdf_png_and_zip_by_content() {
        assert_eq!(
            detect(b"%PDF-1.4\n1 0 obj", "a.pdf", None),
            "application/pdf"
        );
        assert_eq!(
            detect(b"\x89PNG\r\n\x1a\n\0\0\0\rIHDR", "a.png", None),
            "image/png"
        );
        assert_eq!(detect(b"PK\x03\x04\0\0", "a.zip", None), "application/zip");
    }

    #[test]
    fn content_beats_a_misleading_extension_or_declared_type() {
        assert_eq!(detect(b"%PDF-1.4\n", "a.txt", None), "application/pdf");
        assert_eq!(
            detect(
                b"\x89PNG\r\n\x1a\n\0\0\0\rIHDR",
                "a.pdf",
                Some("application/pdf")
            ),
            "image/png"
        );
        assert_eq!(detect(b"PK\x03\x04\0\0", "a.pdf", None), "application/zip");
        assert_eq!(
            detect(b"<!DOCTYPE html><html>", "a.png", Some("image/png")),
            "text/html"
        );
    }

    #[test]
    fn office_documents_are_zips_refined_by_name_or_declared_type() {
        let docx = "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
        assert_eq!(detect(b"PK\x03\x04\0\0", "a.docx", None), docx);
        assert_eq!(detect(b"PK\x03\x04\0\0", "a", Some(docx)), docx);
        assert_eq!(detect(b"PK\x03\x04\0\0", "a.zip", Some(docx)), docx);
        // no magic for plain text: the name decides
        assert_eq!(detect(b"hello\n", "a.docx", None), docx);
    }

    #[test]
    fn svg_and_html_are_identified_by_content() {
        assert_eq!(
            detect(b"<svg xmlns='http://www.w3.org/2000/svg'></svg>", "a", None),
            "image/svg+xml"
        );
        assert_eq!(
            detect(b"<svg/>", "a.html", Some("text/html")),
            "image/svg+xml"
        );
        assert_eq!(
            detect(b"<html><script>alert(1)</script>", "a.txt", None),
            "text/html"
        );
        // Marcel misses leading blanks beyond one character
        assert_eq!(detect(b"  \n<html>", "a", None), BINARY);
    }

    #[test]
    fn binary_without_hints_is_octet_stream_and_hints_fill_in() {
        let bytes: Vec<u8> = (0..=255).collect();
        assert_eq!(detect(&bytes, "a", None), BINARY);
        assert_eq!(detect(&bytes, "a.bin", None), BINARY);
        assert_eq!(detect(&bytes, "a.png", Some("image/png")), "image/png");
        assert_eq!(
            detect(&bytes, "x", Some("application/octet-stream")),
            BINARY
        );
        assert_eq!(detect(b"", "a", None), BINARY);
    }

    #[test]
    fn declared_type_is_parsed_like_marcel() {
        assert_eq!(
            detect(b"hi", "a", Some("TEXT/PLAIN; charset=utf-8")),
            "text/plain"
        );
        assert_eq!(detect(b"hi", "a", Some("text")), BINARY);
        assert_eq!(detect(b"hi", "a.txt", Some(" text/html")), "text/plain");
    }

    #[test]
    fn no_filename_uses_content_and_declared_type_only() {
        assert_eq!(
            detect_content_type(b"%PDF-1.4", None, None),
            "application/pdf"
        );
        assert_eq!(detect_content_type(b"hi", None, None), BINARY);
    }

    #[derive(serde::Deserialize)]
    struct Corpus {
        cases: Vec<Case>,
    }

    #[derive(serde::Deserialize)]
    struct Case {
        label: String,
        data_b64: String,
        filename: Option<String>,
        declared: Option<String>,
        expected: String,
    }

    /// Every answer recorded from Rails' Marcel (`gen_content_type_corpus.rb`).
    #[test]
    fn matches_the_rails_corpus_case_by_case() {
        let raw = include_str!("../../tests/fixtures/content_type_corpus.json");
        let corpus: Corpus = serde_json::from_str(raw).unwrap();
        assert!(corpus.cases.len() > 100);
        let mut failures = Vec::new();
        for case in &corpus.cases {
            let data = base64::engine::general_purpose::STANDARD
                .decode(&case.data_b64)
                .unwrap();
            let got =
                detect_content_type(&data, case.filename.as_deref(), case.declared.as_deref());
            if got != case.expected {
                failures.push(format!(
                    "{}: rails={} rust={}",
                    case.label, case.expected, got
                ));
            }
        }
        assert!(
            failures.is_empty(),
            "{} diverge:\n{}",
            failures.len(),
            failures.join("\n")
        );
    }
}
